#!/usr/bin/env python3
"""Print the chat-visible messages (his text and the assistant's text, no tool
calls or tool results) from the session transcript, from the last user message
containing the anchor up to the compaction summary that follows it."""
import json, sys

path = sys.argv[1]
anchor = sys.argv[2]
out = sys.argv[3]

rows = []
with open(path, 'r', encoding='utf-8', errors='replace') as f:
    for line in f:
        try:
            d = json.loads(line)
        except Exception:
            continue
        t = d.get('type')
        if t not in ('user', 'assistant'):
            continue
        msg = d.get('message') or {}
        content = msg.get('content')
        texts = []
        if isinstance(content, str):
            texts.append(content)
        elif isinstance(content, list):
            for b in content:
                if isinstance(b, dict) and b.get('type') == 'text':
                    texts.append(b.get('text', ''))
        text = '\n'.join(x for x in texts if x and x.strip())
        if not text.strip():
            continue
        rows.append((t, d.get('timestamp', ''), d.get('uuid', ''), text))

# last anchor among user rows
idx = [i for i, r in enumerate(rows) if r[0] == 'user' and anchor in r[3]]
if not idx:
    print('anchor not found', file=sys.stderr); sys.exit(1)
start = idx[-1]
# stop at the compaction summary after it
end = len(rows)
for j in range(start + 1, len(rows)):
    if rows[j][0] == 'user' and rows[j][3].startswith('This session is being continued'):
        end = j
        break

seen = set()
n = 0
with open(out, 'w', encoding='utf-8') as o:
    for t, ts, u, text in rows[start:end]:
        if u in seen:
            continue
        seen.add(u)
        who = 'PAVOL' if t == 'user' else 'CLAUDE'
        o.write(f'\n===== {who} {ts[11:19]} =====\n{text}\n')
        n += 1
print(f'{n} messages, anchors at {idx}, rows {start}..{end}', file=sys.stderr)

