<script>
/* A Select button beside each part's heading selects the part's text, its heading included and its evidence left out, so that iOS's Speak can read it aloud. */
document.querySelectorAll('section.part').forEach(function (sec) {
  var h = sec.querySelector('h2');
  if (!h) return;
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'sel';
  b.setAttribute('aria-label', 'Select this part to have it read aloud');
  h.appendChild(b);
  b.addEventListener('click', function (e) {
    e.preventDefault();
    var r = document.createRange();
    r.setStart(h, 0);
    var ev = sec.querySelector('.evidence');
    if (ev) r.setEndBefore(ev); else r.setEnd(sec, sec.childNodes.length);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  });
});
</script>
